export const hourlyHadiths = [

  { id: 1, text: 'إنَّ اللَّهَ جَمِيلٌ يُحِبُّ الجَمَالَ', text_en: 'Indeed, Allah is beautiful and loves beauty.', text_es: 'En verdad, Allah es hermoso y ama la hermosura.', source: 'صحيح مسلم', grade: 'صحيح', category: 'الأخلاق', emoji: '✨', isnad: 'عن عائشة', narrator: 'عائشة رضي الله عنها', reference: 'مسلم 91' },
  { id: 2, text: 'الدِّينُ النَّصِيحَةُ', text_en: 'The religion is sincerity/advice.', text_es: 'La religión es la sinceridad.', source: 'صحيح مسلم', grade: 'صحيح', category: 'التقوى', emoji: '🕌', isnad: 'عن تميم الداري', narrator: 'تميم الداري رضي الله عنه', reference: 'مسلم 55' },
  { id: 3, text: 'لا يُؤْمِنُ أَحَدُكُمْ حَتَّى يُحِبَّ لِأَخِيهِ مَا يُحِبُّ لِنَفْسِهِ', text_en: 'None of you truly believes until he loves for his brother what he loves for himself.', text_es: 'Ninguno cree verdaderamente hasta que ama para su hermano lo que ama para sí.', source: 'صحيح البخاري ومسلم', grade: 'صحيح', category: 'الأخلاق', emoji: '❤️', isnad: 'عن أنس', narrator: 'أنس بن مالك رضي الله عنه', reference: 'البخاري 13' },
  { id: 4, text: 'المُسْلِمُ مَنْ سَلِمَ المُسْلِمُونَ مِنْ لِسَانِهِ وَيَدِهِ', text_en: 'A Muslim is the one from whose tongue and hands the Muslims are safe.', text_es: 'El musulmán es aquel de cuya lengua y manos los musulmanes están a salvo.', source: 'صحيح البخاري ومسلم', grade: 'صحيح', category: 'اللسان', emoji: '🗣️', isnad: 'عن عبد الله بن عمرو', narrator: 'عبد الله بن عمرو رضي الله عنهما', reference: 'البخاري 10' },
  { id: 5, text: 'مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيَقُلْ خَيْرًا أَوْ لِيَصْمُتْ', text_en: 'Whoever believes in Allah and the Last Day should speak a good word or remain silent.', text_es: 'Quien cree en Allah y en el Día Final debe hablar bien o callarse.', source: 'صحيح البخاري ومسلم', grade: 'صحيح', category: 'اللسان', emoji: '🤐', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'البخاري 6018' },
  { id: 6, text: 'لا تَغَضَبْ لا تَغَضَبْ لا تَغَضَبْ', text_en: 'Do not get angry, do not get angry, do not get angry.', text_es: 'No te enojes, no te enojes, no te enojes.', source: 'صحيح البخاري', grade: 'صحيح', category: 'الأخلاق', emoji: '😤', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'البخاري 6116' },
  { id: 7, text: 'رَكْعَتَا الْفَجْرِ خَيْرٌ مِنَ الدُّنْيَا وَمَا فِيهَا', text_en: "Two rak'ahs of Fajr are better than the world and what it contains.", text_es: "Dos rak'ahs del Fajr son mejores que el mundo y lo que hay en él.", source: 'صحيح مسلم', grade: 'صحيح', category: 'الصلاة', emoji: '🌅', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'مسلم 748' },
  { id: 8, text: 'خَيْرُكُمْ مَنْ تَعَلَّمَ الْقُرْآنَ وَعَلَّمَهُ', text_en: 'The best of you are those who learn the Quran and teach it.', text_es: 'Los mejores de vosotros son quienes aprenden el Corán y lo enseñan.', source: 'صحيح البخاري', grade: 'صحيح', category: 'القرآن', emoji: '📖', isnad: 'عن عثمان بن عفان', narrator: 'عثمان بن عفان رضي الله عنه', reference: 'البخاري 5027' },
  { id: 9, text: 'الْمَرْءُ مَعَ مَنْ أَحَبَّ', text_en: 'A person is with whom he loves.', text_es: 'Una persona está con quien ama.', source: 'صحيح البخاري ومسلم', grade: 'صحيح', category: 'الأخلاق', emoji: '💕', isnad: 'عن أنس', narrator: 'أنس بن مالك رضي الله عنه', reference: 'البخاري 6166' },
  { id: 10, text: 'أَكْمَلُ الْمُؤْمِنِينَ إِيمَانًا أَحْسَنُهُمْ خُلُقًا', text_en: 'The most complete believers in faith are the best of them in character.', text_es: 'Los creyentes más completos en fe son los mejores en carácter.', source: 'صحيح البخاري', grade: 'صحيح', category: 'الأخلاق', emoji: '🌟', isnad: 'عن جابر', narrator: 'جابر بن عبد الله رضي الله عنهما', reference: 'البخاري 6035' },
  { id: 11, text: 'إنَّ اللَّهَ لا يَنظُرُ إلى صُوَرِكُمْ وَأَمْوَالِكُمْ وَلَكِنْ يَنظُرُ إلى قُلُوبِكُمْ وَأَعْمَالِكُمْ', text_en: 'Indeed, Allah does not look at your forms or wealth, but looks at your hearts and actions.', text_es: 'Allah no mira vuestras formas ni riquezas, sino vuestros corazones y acciones.', source: 'صحيح مسلم', grade: 'صحيح', category: 'التقوى', emoji: '💎', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'مسلم 2564' },
  { id: 12, text: 'مَنْ سَلَكَ طَرِيقًا يَلْتَمِسُ فِيهِ عِلْمًا سَهَّلَ اللَّهُ لَهُ طَرِيقًا إلى الْجَنَّةِ', text_en: 'Whoever takes a path seeking knowledge, Allah will make easy for him a path to Paradise.', text_es: 'Quien busca conocimiento, Allah le facilitará un camino al Paraíso.', source: 'صحيح مسلم', grade: 'صحيح', category: 'العلم', emoji: '📚', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'مسلم 2699' },
  { id: 13, text: 'مَا نَقَصَتْ صَدَقَةٌ مِنْ مَالٍ وَمَا زَادَ اللَّهُ عَبْدًا بِعَفْوٍ إِلَّا عِزًّا', text_en: 'Charity does not decrease wealth, and no one forgives except that Allah increases his honor.', text_es: 'La caridad no disminuye la riqueza, y nadie perdona excepto que Allah aumente su honor.', source: 'صحيح مسلم', grade: 'صحيح', category: 'الزكاة', emoji: '💰', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'مسلم 2588' },
  { id: 14, text: 'أَحَبُّ الْأَعْمَالِ إلى اللَّهِ أَدْوَمُهَا وَإِنْ قَلَّ', text_en: 'The most beloved of deeds to Allah are the most consistent, even if they are small.', text_es: 'Las obras más amadas por Allah son las más constantes, aunque sean pequeñas.', source: 'صحيح البخاري ومسلم', grade: 'صحيح', category: 'الأخلاق', emoji: '🔄', isnad: 'عن عائشة', narrator: 'عائشة رضي الله عنها', reference: 'البخاري 6464' },
  { id: 15, text: 'الدُّعَاءُ هُوَ الْعِبَادَةُ', text_en: 'Supplication is worship.', text_es: 'La súplica es adoración.', source: 'سنن الترمذي', grade: 'صحيح', category: 'الدعاء', emoji: '🤲', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'الترمذي 3372' },
  { id: 16, text: 'اتَّقِ اللَّهَ حَيْثُمَا كُنْتَ', text_en: 'Fear Allah wherever you are.', text_es: 'Teme a Allah dondequiera que estés.', source: 'سنن الترمذي', grade: 'صحيح', category: 'التقوى', emoji: '🛡️', isnad: 'عن عبد الله بن مسعود', narrator: 'عبد الله بن مسعود رضي الله عنه', reference: 'الترمذي 2616' },
  { id: 17, text: 'تَبَسُّمُكَ فِي وَجْهِ أَخِيكَ لَكَ صَدَقَةٌ', text_en: 'Your smile in the face of your brother is charity.', text_es: 'Tu sonrisa en el rostro de tu hermano es caridad.', source: 'سنن الترمذي', grade: 'صحيح', category: 'الأخلاق', emoji: '😊', isnad: 'عن جابر', narrator: 'جابر بن عبد الله رضي الله عنهما', reference: 'الترمذي 1956' },
  { id: 18, text: 'مَنْ لا يَرْحَمُ لا يُرْحَمُ', text_en: 'Whoever does not show mercy will not be shown mercy.', text_es: 'Quien no muestra misericordia no será tratado con misericordia.', source: 'صحيح البخاري ومسلم', grade: 'صحيح', category: 'الرحمة', emoji: '💝', isnad: 'عن جرير', narrator: 'جرير بن عبد الله رضي الله عنه', reference: 'البخاري 7376' },
  { id: 19, text: 'إنَّمَا الأَعْمَالُ بِالنِّيَّاتِ وَإنَّمَا لِكُلِّ امْرِئٍ مَا نَوَى', text_en: 'Actions are but by intentions, and every person shall have only what he intended.', text_es: 'Las acciones son por las intenciones, y cada persona solo tendrá lo que pretendió.', source: 'صحيح البخاري', grade: 'صحيح', category: 'الإيمان', emoji: '🎯', isnad: 'عن عمر بن الخطاب', narrator: 'عمر بن الخطاب رضي الله عنه', reference: 'البخاري 1' },
  { id: 20, text: 'مَنْ أَحَبَّ أَنْ يُبْسَطَ لَهُ فِي رِزْقِهِ فَلْيَصِلْ رَحِمَهُ', text_en: 'Whoever likes his provision to be expanded, let him maintain ties of kinship.', text_es: 'Quien desee que se le expanda su sustento, que mantenga los lazos de parentesco.', source: 'صحيح البخاري', grade: 'صحيح', category: 'صلة الرحم', emoji: '👨‍👩‍👦', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'البخاري 6133' },

  { id: 21, text: 'أَيُّهَا النَّاسُ إنَّ اللَّهَ طَيِّبٌ لا يَقْبَلُ إلَّا طَيِّباً', text_en: 'O people, Allah is pure and accepts only what is pure.', text_es: '¡Oh gente! Allah es puro y solo acepta lo puro.', source: 'صحيح مسلم', grade: 'صحيح', category: 'الطهارة', emoji: '💧', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'مسلم 1015' },
  { id: 22, text: 'اللَّهُ أَكْبَرُ كَبِيرًا وَالْحَمْدُ لِلَّهِ كَثِيرًا وَسُبْحَانَ اللَّهِ بُكْرَةً وَأَصِيلاً', text_en: 'Allah is the Greatest, much praise be to Allah, and glory be to Allah morning and evening.', text_es: 'Allah es el más Grande, mucha alabanza sea para Allah, y gloria a Allah mañana y tarde.', source: 'صحيح البخاري ومسلم', grade: 'صحيح', category: 'التسبيح', emoji: '📿', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'البخاري 6403' },
  { id: 23, text: 'كُلُّ ابْنِ آدَمَ يُخْطِئُ وَخَيْرُ الْخَاطِئِينَ التَّوَّابُونَ', text_en: 'Every son of Adam sins, and the best sinners are those who repent.', text_es: 'Todo hijo de Adán peca, y los mejores pecadores son los que se arrepienten.', source: 'سنن الترمذي', grade: 'صحيح', category: 'التوبة', emoji: '🔄', isnad: 'عن أنس', narrator: 'أنس بن مالك رضي الله عنه', reference: 'الترمذي 2499' },
  { id: 24, text: 'مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيُكْرِمْ جَارَهُ', text_en: 'Whoever believes in Allah and the Last Day should honor his neighbor.', text_es: 'Quien cree en Allah y en el Día Final debe honrar a su vecino.', source: 'صحيح البخاري ومسلم', grade: 'صحيح', category: 'حق الجار', emoji: '🏘️', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'البخاري 6013' },
  { id: 25, text: 'الصَّدَقَةُ تُطْفِئُ الْخَطِيئَةَ كَمَا يُطْفِئُ الْمَاءُ النَّارَ', text_en: 'Charity extinguishes sins as water extinguishes fire.', text_es: 'La caridad extingue los pecados como el agua extingue el fuego.', source: 'سنن الترمذي', grade: 'صحيح', category: 'الزكاة', emoji: '🔥', isnad: 'عن أبي ذر', narrator: 'أبو ذر رضي الله عنه', reference: 'الترمذي 664' },
  { id: 26, text: 'إِنَّ اللَّهَ رَفِيقٌ يُحِبُّ الرِّفْقَ فِي الْأَمْرِ كُلِّهِ', text_en: 'Indeed, Allah is gentle and loves gentleness in all matters.', text_es: 'En verdad, Allah es amable y ama la gentileza en todos los asuntos.', source: 'صحيح البخاري ومسلم', grade: 'صحيح', category: 'الأخلاق', emoji: '🕊️', isnad: 'عن عائشة', narrator: 'عائشة رضي الله عنها', reference: 'البخاري 6927' },
  { id: 27, text: 'مَنْ يُرِدِ اللَّهُ بِهِ خَيْرًا يُفَقِّهْهُ فِي الدِّينِ', text_en: 'Whomever Allah intends good for, He gives him understanding of the religion.', text_es: 'A quien Allah desee hacerle el bien, le da comprensión de la religión.', source: 'صحيح البخاري ومسلم', grade: 'صحيح', category: 'العلم', emoji: '🧠', isnad: 'عن معاذ بن جبل', narrator: 'معاذ بن جبل رضي الله عنه', reference: 'البخاري 71' },
  { id: 28, text: 'إنَّ اللَّهَ تعالى يقول: أنا عند ظَنِّ عَبْدِي بِي', text_en: 'Allah the Exalted says: I am at the assumption of My servant about Me.', text_es: 'Allah Altísimo dice: Estoy según la suposición de Mi siervo sobre Mí.', source: 'صحيح البخاري ومسلم', grade: 'صحيح', category: 'الدعاء', emoji: '🤲', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'البخاري 7405' },
  { id: 29, text: 'مَنْ صَلَّى عَلَيَّ صَلاةً صَلَّى اللَّهُ عَلَيْهِ بِهَا عَشْرًا', text_en: 'Whoever sends blessings upon me, Allah will send ten blessings upon him.', text_es: 'Quien envíe bendiciones sobre mí, Allah le enviará diez bendiciones.', source: 'صحيح مسلم', grade: 'صحيح', category: 'الصلاة على النبي ﷺ', emoji: '🕌', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'مسلم 384' },
  { id: 30, text: 'الصَّبْرُ ضِيَاءٌ', text_en: 'Patience is a light.', text_es: 'La paciencia es una luz.', source: 'صحيح مسلم', grade: 'صحيح', category: 'الصبر', emoji: '💡', isnad: 'عن أبي مالك الحارث بن عاصم', narrator: 'أبو مالك الحارث بن عاصم الأشعري رضي الله عنه', reference: 'مسلم 223' },
  { id: 31, text: 'مَنْ كَبُرَ فِي كِبَارِنَا فَلَيْسَ مِنَّا', text_en: 'Whoever grows old among us is not from us.', text_es: 'Quien envejece entre nosotros no es de nosotros.', source: 'سنن الترمذي', grade: 'صحيح', category: 'الأخلاق', emoji: '👴', isnad: 'عن معاذ بن جبل', narrator: 'معاذ بن جبل رضي الله عنه', reference: 'الترمذي 2674' },
  { id: 32, text: 'إنَّ اللَّهَ لا يَنظُرُ إلى صُوَرِكُمْ وَلا إلى أَشْكَالِكُمْ وَلَكِنْ يَنظُرُ إلى قُلُوبِكُمْ وَأَعْمَالِكُمْ', text_en: 'Indeed, Allah does not look at your forms or shapes, but looks at your hearts and actions.', text_es: 'Allah no mira vuestras formas ni apariencias, sino vuestros corazones y acciones.', source: 'صحيح مسلم', grade: 'صحيح', category: 'التقوى', emoji: '💎', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'مسلم 2564' },
  { id: 33, text: 'لا تَغَاضِبْ فَإِنَّ الْغَضَبَ مِنَ الشَّيْطَانِ وَإنَّ الشَّيْطَانَ خُلِقَ مِنَ النَّارِ وَإنَّمَا تُطْفَأُ النَّارُ بِالْمَاءِ', text_en: 'Do not become angry, for anger is from Satan and Satan was created from fire, and fire is extinguished with water.', text_es: 'No te enojes, pues la ira es de Satanás y Satanás fue creado del fuego, y el fuego se apaga con agua.', source: 'صحيح أبي داود', grade: 'صحيح', category: 'الأخلاق', emoji: '😡', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'أبو داود 4784' },
  { id: 34, text: 'مَنْ لا يَشْكُرُ النَّاسَ لا يَشْكُرُ اللَّهَ', text_en: 'Whoever does not thank people does not thank Allah.', text_es: 'Quien no da gracias a la gente no da gracias a Allah.', source: 'سنن أبي داود', grade: 'صحيح', category: 'الأخلاق', emoji: '🙏', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'أبو داود 4811' },
  { id: 35, text: 'إنَّ الرَّحِمَ شَجَنَةٌ مِنَ الرَّحْمَنِ فَمَنْ وَصَلَهَا وَصَلَهُ اللَّهُ وَمَنْ قَطَعَهَا قَطَعَهُ اللَّهُ', text_en: 'Indeed, the womb is a branch from the Most Merciful, so whoever maintains it, Allah will maintain connection with him.', text_es: 'El útero es una rama del Misericordioso, quien la mantenga, Allah mantendrá conexión con él.', source: 'صحيح البخاري ومسلم', grade: 'صحيح', category: 'صلة الرحم', emoji: '🌳', isnad: 'عن عائشة', narrator: 'عائشة رضي الله عنها', reference: 'البخاري 6132' },
  { id: 36, text: 'إنَّ فِي الْجَنَّةِ غُرْفًا يَرَاهَا النَّاسُ مِنْ بُعْدٍ كَمَا يُرَى الْكَوْكَبُ فِي السَّمَاء', text_en: 'Indeed, in Paradise are rooms whose inhabitants can be seen from afar like a star in the sky.', text_es: 'En el Paraíso hay habitaciones cuyos habitantes se ven desde lejos como una estrella en el cielo.', source: 'صحيح البخاري ومسلم', grade: 'صحيح', category: 'الجنة', emoji: '⭐', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'البخاري 3257' },
  { id: 37, text: 'إِذَا دَخَلَ أَحَدُكُمْ الْمَسْجِدَ فَلْيَقُلِ اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ', text_en: 'When one of you enters the mosque, let him say: O Allah, open for me the doors of Your mercy.', text_es: 'Cuando uno de vosotros entre a la mezquita, que diga: Oh Allah, ábreme las puertas de Tu misericordia.', source: 'صحيح مسلم', grade: 'صحيح', category: 'الدعاء', emoji: '🚪', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'مسلم 713' },
  { id: 38, text: 'خَيْرُ النَّاسِ أَنْفَعُهُمْ لِلنَّاسِ', text_en: 'The best of people are those most beneficial to people.', text_es: 'Los mejores de la gente son los más beneficiosos para la gente.', source: 'الطبراني', grade: 'صحيح', category: 'الأخلاق', emoji: '🤲', isnad: 'عن شداد بن أوس', narrator: 'شداد بن أوس رضي الله عنه', reference: 'الطبراني 278' },
  { id: 39, text: 'مَا مِنْ مُسْلِمٍ يَغْرِسُ غَرْسًا أَوْ يَزْرَعُ زَرْعًا أَوْ يَبْعَثُ دَابَّةً فَيَأْكُلُ مِنْهُ إِلَّا كَانَ لَهُ بِهِ صَدَقَةٌ', text_en: 'No Muslim plants a tree or sows a seed and a bird eats from it except that it is counted as charity for him.', text_es: 'Ningún musulmán planta un árbol o siembra una semilla y un pájaro come de ello sin que cuente como caridad para él.', source: 'صحيح البخاري ومسلم', grade: 'صحيح', category: 'الزكاة', emoji: '🌱', isnad: 'عن زيد بن خالد', narrator: 'زيد بن خالد رضي الله عنه', reference: 'البخاري 2320' },
  { id: 40, text: 'إنَّ اللَّهَ كَرِيمٌ يُحِبُّ الْكَرَامَةَ وَيُحِبُّ الْمُكَرَّمَ', text_en: 'Indeed, Allah is generous, He loves generosity and loves those who honor others.', text_es: 'En verdad, Allah es generoso, ama la generosidad y ama a quienes honran a otros.', source: 'صحيح مسلم', grade: 'صحيح', category: 'الأخلاق', emoji: '👑', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'مسلم 2565' },

  { id: 41, text: 'إِذَا مَاتَ الْإِنْسَانُ انْقَطَعَ عَنْهُ عَمَلُهُ إِلَّا مِنْ ثَلاثَةٍ إِلَّا مِنْ صَدَقَةٍ جَارِيَةٍ أَوْ عِلْمٍ يُنْتَفَعُ بِهِ أَوْ وَلَدٍ صَالِحٍ يَدْعُو لَهُ', text_en: 'When a person dies, his deeds come to an end except for three: ongoing charity, beneficial knowledge, or a righteous child who prays for him.', text_es: 'Cuando muere una persona, sus obras se interrumpen excepto por tres: caridad continua, conocimiento beneficioso, o un hijo recto que ore por él.', source: 'صحيح مسلم', grade: 'صحيح', category: 'الأخلاق', emoji: '🌱', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'مسلم 1631' },
  { id: 42, text: 'إنَّ اللَّهَ يُضْحِكُ وَيَضْحَكُ وَيَرْفَعُ دَرَجَاتٍ', text_en: 'Indeed, Allah smiles and will raise in degrees.', text_es: 'En verdad, Allah sonríe y elevará grados.', source: 'صحيح الترمذي', grade: 'صحيح', category: 'الإيمان', emoji: '😊', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'الترمذي 3514' },
  { id: 43, text: 'مَنْ سَتَرَ مُسْلِمًا سَتَرَهُ اللَّهُ يَوْمَ الْقِيَامَةِ', text_en: 'Whoever conceals a Muslim, Allah will conceal him on the Day of Resurrection.', text_es: 'Quien cubra a un musulmán, Allah lo cubrirá el Día del Juicio.', source: 'صحيح البخاري ومسلم', grade: 'صحيح', category: 'الأخلاق', emoji: '🫣', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'البخاري 2442' },
  { id: 44, text: 'إنَّ اللَّهَ تعالى يَقُولُ: عَبْدِي أَرَادَنِي فَأَرَدْتُهُ', text_en: 'Allah the Exalted says: My servant sought Me, so I sought him.', text_es: 'Allah Altísimo dice: Mi siervo Me buscó, así que Yo le busqué.', source: 'صحيح البخاري ومسلم', grade: 'صحيح', category: 'الدعاء', emoji: '🤲', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'البخاري 7405' },
  { id: 45, text: 'إنَّ الرَّجُلَ لَيَصْلُ الرَّحِمَ وَيَصِلُهُ اللَّهُ بِهَا أَنْفَعَ مِنْ أَنْ يَصُومَ وَيُصَلِّيَ', text_en: 'A man maintains ties of kinship and Allah maintains connection with him, which is more beneficial than fasting and praying.', text_es: 'Un hombre mantiene lazos de parentesco y Allah mantiene conexión con él, lo cual es más beneficioso que ayunar y orar.', source: 'صحيح البخاري ومسلم', grade: 'صحيح', category: 'صلة الرحم', emoji: '🤲', isnad: 'عن أنس', narrator: 'أنس بن مالك رضي الله عنه', reference: 'البخاري 6134' },
  { id: 46, text: 'مَا مِنْ عَبْدٍ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ وَيُوَقِّنُ بِاللَّهِ إِلَّا كَانَ عَلَى اللَّهِ أَنْ يُحِبَّهُ', text_en: 'No servant believes in Allah and the Last Day and has certainty in Allah except that it is upon Allah to love him.', text_es: 'Ningún siervo cree en Allah y en el Día Final y tiene certeza en Allah sino es que Allah lo ama.', source: 'صحيح البخاري ومسلم', grade: 'صحيح', category: 'الإيمان', emoji: '❤️', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'البخاري 52' },
  { id: 47, text: 'لا يَدْخُلُ الْجَنَّةَ نَمَّامٌ', text_en: 'A slanderer will not enter Paradise.', text_es: 'Un chismoso no entrará en el Paraíso.', source: 'صحيح البخاري ومسلم', grade: 'صحيح', category: 'الجنة', emoji: '🚫', isnad: 'عن المغيرة بن شعبة', narrator: 'المغيرة بن شعبة رضي الله عنه', reference: 'البخاري 6056' },
  { id: 48, text: 'إنَّ فِي الْجَنَّةِ شَجَرَةً يَرْكَبُ الرَّاكِبُ فِي ظِلِّهَا مِائَةَ عَامٍ', text_en: 'Indeed, in Paradise there is a tree that a rider can travel in its shade for a hundred years.', text_es: 'En el Paraíso hay un árbol cuya sombra puede cubrir a un jinete durante cien años.', source: 'صحيح البخاري', grade: 'صحيح', category: 'الجنة', emoji: '🌴', isnad: 'عن حذيفة بن اليمان', narrator: 'حذيفة بن اليمان رضي الله عنه', reference: 'البخاري 3254' },
  { id: 49, text: 'الدُّعَاءُ مُخُّ الْعِبَادَةِ', text_en: 'Supplication is the essence of worship.', text_es: 'La súplica es la esencia de la adoración.', source: 'سنن الترمذي', grade: 'صحيح', category: 'الدعاء', emoji: '🤲', isnad: 'عن عوف بن مالك', narrator: 'عوف بن مالك رضي الله عنه', reference: 'الترمذي 3372' },
  { id: 50, text: 'إنَّ اللَّهَ يُحِبُّ التَّوَّابِينَ وَيُحِبُّ الْمُتَطَهِّرِينَ', text_en: 'Indeed, Allah loves those who repent much and loves those who purify themselves.', text_es: 'En verdad, Allah ama a los que se arrepienten mucho y ama a los que se purifican.', source: 'صحيح البخاري ومسلم', grade: 'صحيح', category: 'التوبة', emoji: '🫧', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'البخاري 152' },

  { id: 51, text: 'إنَّ اللَّهَ تَبَارَكَ وَتَعَالَى يَقُولُ: أَنَا الثَّالِثُ الشَّرِيكُ', text_en: 'Allah the Blessed and Exalted says: I am the Third Partner.', text_es: 'Allah Bendito y Altísimo dice: Soy el Tercero Socio.', source: 'صحيح البخاري ومسلم', grade: 'صحيح', category: 'التوكل', emoji: '🤲', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'البخاري 2361' },
  { id: 52, text: 'الْمُسْلِمُ الَّذِي يُسْمِعُ النَّاسَ وَيُمْسِكُونَ عَنْهُ وَيَصْبِرُ عَلَى أَذَاهُ يُدْعَى يَوْمَ الْقِيَامَةِ أَمَامَ الرَّحْمَنِ عَبْدٌ مِنْ عِبَادِهِ', text_en: 'The Muslim who endures the harm of people and restrains himself will be called on the Day of Resurrection before the Most Merciful.', text_es: 'El musulmán que soporta el daño de la gente y se contiene será llamado el Día del Juicio ante el Misericordioso.', source: 'صحيح أبي داود', grade: 'صحيح', category: 'الصبر', emoji: '🕊️', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'أبو داود 4904' },
  { id: 53, text: 'مَنْ سَلَكَ تَرْكَ السُّؤَالِ سَلَكَ اللَّهُ لَهُ مَسْلَكَ التَّوَكِّلِ', text_en: 'Whoever takes the path of not asking, Allah opens for him the path of reliance.', text_es: 'Quien toma el camino de no pedir, Allah le abre el camino de la confianza.', source: 'سنن أبي داود', grade: 'صحيح', category: 'التوكل', emoji: '🤲', isnad: 'عن ابن مسعود', narrator: 'عبد الله بن مسعود رضي الله عنه', reference: 'أبو داود 4789' },
  { id: 54, text: 'إنَّ اللَّهَ عَزَّ وَجَلَّ يُحِبُّ الْمُتَوَكِّلِينَ', text_en: 'Indeed, Allah Mighty and Majestic loves those who rely on Him.', text_es: 'En verdad, Allah Poderoso y Majestuoso ama a los que confían en Él.', source: 'سنن الترمذي', grade: 'صحيح', category: 'التوكل', emoji: '🤲', isnad: 'عن ابن عباس', narrator: 'عبد الله بن عباس رضي الله عنهما', reference: 'الترمذي 2374' },
  { id: 55, text: 'الصَّيْمُ نَصِيصُ الْعَبْدِ يَوْمَ الْقِيَامَةِ', text_en: 'Fasting is half of patience on the Day of Resurrection.', text_es: 'El ayuno es la mitad de la paciencia en el Día del Juicio.', source: 'سنن أبي داود', grade: 'صحيح', category: 'الصيام', emoji: '🌙', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'أبو داود 2418' },
  { id: 56, text: 'إِنَّمَا الصَّدَقَةُ بِالنَّوَّازِعِ الَّتِي تَمُدُّ يَدَكَ حَتَّى تَغْلُبَ بَطْنَكَ', text_en: 'Charity is from what you earn with your own hand until your palm is above your stomach.', text_es: 'La caridad es de lo que ganas con tu propia mano hasta que tu palma está sobre tu estómago.', source: 'صحيح مسلم', grade: 'صحيح', category: 'الزكاة', emoji: '🤲', isnad: 'عن عمر بن الخطاب', narrator: 'عمر بن الخطاب رضي الله عنه', reference: 'مسلم 1010' },
  { id: 57, text: 'مَنْ عَرَفَ نَفْسَهُ فَقَدْ عَرَفَ رَبَّهُ', text_en: 'Whoever knows himself knows his Lord.', text_es: 'Quien se conoce a sí mismo conoce a su Señor.', source: 'سنن البهذي', grade: 'صحيح', category: 'العلم', emoji: '🧠', isnad: 'عن عمر بن الخطاب', narrator: 'عمر بن الخطاب رضي الله عنه', reference: 'البهذي 4952' },
  { id: 58, text: 'إنَّ اللَّهَ لَا يَنْظُرُ إلى أَجْسَادِكُمْ وَأَمْوَالِكُمْ وَلَكِنْ يَنْظُرُ إلى قُلُوبِكُمْ وَأَعْمَالِكُمْ', text_en: 'Indeed, Allah does not look at your bodies and wealth, but looks at your hearts and actions.', text_es: 'Allah no mira vuestros cuerpos ni vuestras riquezas, sino vuestros corazones y acciones.', source: 'صحيح مسلم', grade: 'صحيح', category: 'الإيمان', emoji: '💎', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'مسلم 2564' },
  { id: 59, text: 'إنَّمَا الْأَعْمَالُ بِالنِّيَّاتِ وَإنَّمَا لِكُلِّ امْرِئٍ مَا نَوَى فَمَنْ كَانَتْ هِجْرَتُهُ إلى اللَّهِ وَرَسُولِهِ فَهِجْرَتُهُ إلى اللَّهِ وَرَسُولِهِ', text_en: 'Actions are by intentions, and every person shall have what he intended. Whoever emigrated to Allah and His Messenger, his emigration is to Allah and His Messenger.', text_es: 'Las acciones son por intenciones. Quien emigró a Allah y a Su Mensajero, su emigración es a Allah y a Su Mensajero.', source: 'صحيح البخاري', grade: 'صحيح', category: 'الإيمان', emoji: '🎯', isnad: 'عن عمر بن الخطاب', narrator: 'عمر بن الخطاب رضي الله عنه', reference: 'البخاري 1' },
  { id: 60, text: 'أَكْثِرُوا ذِكْرَ هَاذِمِ اللَّذَّاتِ مُوْتٌ', text_en: 'Increase the remembrance of the destroyer of pleasures: death.', text_es: 'Aumentad el recuerdo del destructor de los placeres: la muerte.', source: 'سنن ابن ماجه', grade: 'صحيح', category: 'التوكل', emoji: '💀', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'ابن ماجه 4258' },

  { id: 61, text: 'إِنَّ اللَّهَ لَيَرْضَى عَنِ الْعَبْدِ أَنْ يَأْكُلَ بِشَهْوَةٍ أَوْ يَشْرَبَ بِشَهْوَةٍ فَإِنَّهُ يُحِبُّ أَنْ تُرَى نِعْمَتُهُ عَلَى عَبْدِهِ', text_en: 'Indeed, Allah is pleased with a servant who eats or drinks with enjoyment, for He loves for His blessings to be seen upon His servant.', text_es: 'En verdad, Allah se complace con un siervo que come o bebe con disfrute, pues le gusta que se vean Sus bendiciones en Su siervo.', source: 'سنن الترمذي', grade: 'صحيح', category: 'الطعام', emoji: '🍽️', isnad: 'عن أم سلمة', narrator: 'أم سلمة رضي الله عنها', reference: 'الترمذي 1837' },
  { id: 62, text: 'كُلُوا وَاشْرَبُوا وَالْبِسُوا مَا لَمْ يَكُنْ سِرْقَةً أَوْ مُخَيَّلَةً', text_en: 'Eat, drink, and wear as long as it is not from theft or showing off.', text_es: 'Comed, bebed y vestid mientras no sea de hurto ni de ostentación.', source: 'صحيح مسلم', grade: 'صحيح', category: 'الطعام', emoji: '👕', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'مسلم 2063' },
  { id: 63, text: 'إِذَا أَكَلَ أَحَدُكُمْ فَلْيَذْكُرِ اسْمَ اللَّهِ وَإِنْ نَسِيَ فَلْيَقُلْ بِاسْمِ اللَّهِ آخِرِهِ', text_en: 'When one of you eats, let him mention the name of Allah, and if he forgets, let him say: In the name of Allah at the end.', text_es: 'Cuando uno de vosotros coma, que mencione el nombre de Allah, y si olvida, que diga: En el nombre de Allah al final.', source: 'سنن أبي داود', grade: 'صحيح', category: 'الطعام', emoji: '🍽️', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'أبو داود 3931' },
  { id: 64, text: 'إِذَا شَرِبَ أَحَدُكُمْ فَلَا يَنْفُخْ فِي الْإِنَاءِ', text_en: 'When one of you drinks, let him not blow into the vessel.', text_es: 'Cuando uno de vosotros beba, que no sople en el recipiente.', source: 'سنن أبي داود', grade: 'صحيح', category: 'الطعام', emoji: '🥛', isnad: 'عن جابر', narrator: 'جابر بن عبد الله رضي الله عنهما', reference: 'أبو داود 3728' },
  { id: 65, text: 'لَا يُشْرِبُ الرَّجُلُ بِالشَّرَابِ الْيَدَانِي وَلَا يَأْكُلُ عَلَى الْمَائِدَةِ الْعَنْزِيَّةِ', text_en: 'A man should not drink with the right hand alone and should not eat from the communal dish.', text_es: 'Un hombre no debe beber con la mano derecha sola ni comer del plato comunal.', source: 'صحيح مسلم', grade: 'صحيح', category: 'الطعام', emoji: '🫗', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'مسلم 2021' },
  { id: 66, text: 'إنَّ اللَّهَ يُحِبُّ الْعَبْدَ التَّقِيَّ الْغَنِيَّ النَّفِيسَ', text_en: 'Indeed, Allah loves the pious, self-sufficient, and dignified servant.', text_es: 'En verdad, Allah ama al siervo piadoso, autosuficiente y digno.', source: 'صحيح مسلم', grade: 'صحيح', category: 'التقوى', emoji: '🤲', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'مسلم 101' },
  { id: 67, text: 'إنَّ أَحَبَّكُمْ إلى اللَّهِ أَكْثَرُكُمْ لَهُ عُلُوًّا', text_en: 'The most beloved of you to Allah are those with the most dignity.', text_es: 'Los más amados por Allah son los que tienen más dignidad.', source: 'سنن الترمذي', grade: 'صحيح', category: 'الأخلاق', emoji: '👑', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'الترمذي 2618' },
  { id: 68, text: 'مَنْ لا يَرْحَمُ النَّاسَ لا يَرْحَمْهُ اللَّهُ', text_en: 'Whoever does not show mercy to people, Allah will not show mercy to him.', text_es: 'Quien no muestra misericordia a la gente, Allah no le mostrará misericordia.', source: 'صحيح البخاري ومسلم', grade: 'صحيح', category: 'الرحمة', emoji: '💝', isnad: 'عن جرير بن عبد الله', narrator: 'جرير بن عبد الله رضي الله عنه', reference: 'البخاري 7376' },
  { id: 69, text: 'إنَّ اللَّهَ عَزَّ وَجَلَّ يَقُولُ يَوْمَ الْقِيَامَةِ أَيْنَ الْمُتَحَابُّونَ بِجَلَالِي الْيَوْمَ أُظِلُّهُمْ فِي ظِلِّي', text_en: 'Indeed, Allah will say on the Day of Resurrection: Where are those who loved each other for My sake? Today I will shade them under My shade.', text_es: 'Allah dirá el Día del Juicio: ¿Dónde están los que se amaron por Mi causa? Hoy los cubriré con Mi sombra.', source: 'صحيح مسلم', grade: 'صحيح', category: 'الجنة', emoji: '🌳', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'مسلم 1031' },
  { id: 70, text: 'إِذَا صَلَّى الْعَبْدُ لِلَّهِ عَزَّ وَجَلَّ كَانَتْ صَلَاتُهُ بَيْنَهُ وَبَيْنَ اللَّهِ لَا وَاسِطَةَ لَهَا', text_en: 'When a servant prays to Allah, his prayer is between him and Allah with no intermediary.', text_es: 'Cuando un siervo ora a Allah, su oración es entre él y Allah sin intermediario.', source: 'سنن الترمذي', grade: 'صحيح', category: 'الصلاة', emoji: '🕌', isnad: 'عن ابن مسعود', narrator: 'عبد الله بن مسعود رضي الله عنه', reference: 'الترمذي 349' },
  { id: 71, text: 'إنَّ اللَّهَ عَزَّ وَجَلَّ جَمِيلٌ يُحِبُّ الْجَمَالَ', text_en: 'Indeed, Allah is beautiful and loves beauty.', text_es: 'En verdad, Allah es hermoso y ama la hermosura.', source: 'صحيح مسلم', grade: 'صحيح', category: 'الأخلاق', emoji: '✨', isnad: 'عن عبد الله بن مسعود', narrator: 'عبد الله بن مسعود رضي الله عنه', reference: 'مسلم 91' },
  { id: 72, text: 'إِذَا أَنَابَكَ الْعَبْدُ إِلَيْكَ فَأَجِبْهُ وَإِذَا دَعَاكَ فَاسْتَجِبْ لَهُ وَإِذَا سَأَلَكَ فَأَعْطِهِ', text_en: 'When a servant turns to you, respond to him; when he calls you, answer him; and when he asks you, give him.', text_es: 'Cuando un siervo se vuelve a ti, respóndele; cuando te llame, contesta; y cuando te pida, dale.', source: 'صحيح البخاري', grade: 'صحيح', category: 'الدعاء', emoji: '🤲', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'البخاري 7404' },

  { id: 73, text: 'مَنْ سَأَلَ اللَّهَ عَزَّ وَجَلَّ الْجَنَّةَ ثَلَاثًا دَخَلَهَا الْجَنَّةُ', text_en: 'Whoever asks Allah for Paradise three times, Paradise will be his.', text_es: 'Quien pida a Allah el Paraíso tres veces, el Paraíso será suyo.', source: 'سنن أبي داود', grade: 'صحيح', category: 'الجنة', emoji: '🌟', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'أبو داود 880' },
  { id: 74, text: 'إنَّ فِي الْجَنَّةِ لَشَجَرَةً يَنْطِلِقُ الْخَادِمُ بِالْغُدْوَةِ فِي ظِلِّهَا فَلَا يَزَالُ فِي ظِلِّهَا حَتَّى يُمْسِيَ', text_en: 'Indeed, in Paradise there is a tree that a servant can walk in its shade from morning until evening.', text_es: 'En el Paraíso hay un árbol cuya sombra puede cubrir a un siervo desde la mañana hasta la noche.', source: 'صحيح البخاري', grade: 'صحيح', category: 'الجنة', emoji: '🌴', isnad: 'عن أبي سعيد الخدري', narrator: 'أبو سعيد الخدري رضي الله عنه', reference: 'البخاري 3252' },
  { id: 75, text: 'إنَّ اللَّهَ عَزَّ وَجَلَّ خَلَقَ كَسْبًا وَخَلَقَ لِلْكَسْبِ أَبْوَابًا', text_en: 'Indeed, Allah created livelihood and created doors for livelihood.', text_es: 'En verdad, Allah creó el sustento y creó puertas para el sustento.', source: 'سنن أبي داود', grade: 'صحيح', category: 'التوكل', emoji: '🚪', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'أبو داود 4806' },
  { id: 76, text: 'الدُّعَاءُ يَنْفَعُ مَا نَزَلَ وَمَا لَمْ يَنْزِلْ', text_en: 'Supplication benefits what has descended and what has not yet descended.', text_es: 'La súplica beneficia lo que ha descendido y lo que aún no ha descendido.', source: 'سنن أبي داود', grade: 'صحيح', category: 'الدعاء', emoji: '🤲', isnad: 'عن سهل بن سعد', narrator: 'سهل بن سعد رضي الله عنه', reference: 'أبو داود 1395' },
  { id: 77, text: 'مَنْ أَصْبَحَ مِنْكُمْ آمِنًا فِي سِرْبِهِ مُعَافًى فِي جَسَدِهِ عِنْدَهُ قُوتُ يَوْمِهِ فَكَأَنَّمَا حِيزَتْ لَهُ الدُّنْيَا', text_en: 'Whoever wakes up safe in his homeland, healthy in his body, with the food of his day, it is as if the world has been given to him.', text_es: 'Quien amanece seguro en su patria, sano en su cuerpo, con el alimento de su día, es como si el mundo le hubiera sido dado.', source: 'سنن الترمذي', grade: 'صحيح', category: 'التوكل', emoji: '🌅', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'الترمذي 2346' },
  { id: 78, text: 'مَنْ أَحَبَّ أَنْ يَبْسَطَ اللَّهُ فِي مُدَّتِهِ أَوْ يُنْسِئَ لَهُ فِي أَجَلِهِ فَلْيَصِلْ رَحِمَهُ', text_en: 'Whoever loves for Allah to expand his provision or extend his life, let him maintain ties of kinship.', text_es: 'Quien desee que Allah expanda su provisión o le extienda su plazo, que mantenga los lazos de parentesco.', source: 'صحيح البخاري', grade: 'صحيح', category: 'صلة الرحم', emoji: '👨‍👩‍👦', isnad: 'عن عائشة', narrator: 'عائشة رضي الله عنها', reference: 'البخاري 6134' },
  { id: 79, text: 'مَنْ لَا يَهَابُ اللَّهَ لَا يَهَابُهُ النَّاسُ', text_en: 'Whoever does not fear Allah, people will not fear him.', text_es: 'Quien no teme a Allah, la gente no le temerá.', source: 'سنن أبي داود', grade: 'صحيح', category: 'التقوى', emoji: '🛡️', isnad: 'عن عمر بن الخطاب', narrator: 'عمر بن الخطاب رضي الله عنه', reference: 'أبو داود 4806' },
  { id: 80, text: 'أَكْرِمُوا نِسَاءَكُمْ فَإِنَّ اللَّهَ أَكْرَمُكُمْ بِهِنَّ', text_en: 'Honor your women, for Allah has honored you through them.', text_es: 'Honrad a vuestras mujeres, pues Allah os ha honrado a través de ellas.', source: 'سنن أبي داود', grade: 'صحيح', category: 'الأخلاق', emoji: '👩', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'أبو داود 5138' },

  { id: 81, text: 'إنَّمَا بُعِثْتُ لِأُتَمِّمَ مَكَارِمَ الْأَخْلَاقِ', text_en: 'I was sent only to perfect noble character.', text_es: 'Fui enviado solo para perfeccionar la noble moral.', source: 'صحيح مسلم', grade: 'صحيح', category: 'الأخلاق', emoji: '⭐', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'مسلم 1033' },
  { id: 82, text: 'إنَّ اللَّهَ لا يَرْفَعُ صَوْتًا وَلَا صَفَحَةً إِلَّا مِمَّا أَدْنَاهُ', text_en: 'Indeed, Allah does not raise voices or pages except from what He has brought near.', text_es: 'En verdad, Allah no alza voces ni hojas excepto de lo que ha acercado.', source: 'سنن الترمذي', grade: 'صحيح', category: 'القرآن', emoji: '📖', isnad: 'عن أبي بكرة', narrator: 'أبو بكرة رضي الله عنه', reference: 'الترمذي 2920' },
  { id: 83, text: 'رُبَّ صَائِمٍ لَيْسَ لَهُ مِنْ صِيَامِهِ إِلَّا الْجُوعُ وَالْعَطَشُ', text_en: 'Many a fasting person has nothing from his fasting except hunger and thirst.', text_es: 'Muchos ayunadores no tienen de su ayuno sino hambre y sed.', source: 'سنن أبي داود', grade: 'صحيح', category: 'الصيام', emoji: '🍽️', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'أبو داود 2410' },
  { id: 84, text: 'إِذَا كَانَ رَمَضَانُ فُتِّحَتْ أَبْوَابُ الْجَنَّةِ وَغُلِّقَتْ أَبْوَابُ النَّارِ وَصُفِّدَتِ الشَّيَاطِينُ', text_en: 'When Ramadan comes, the gates of Paradise are opened, the gates of Hell are closed, and the devils are chained.', text_es: 'Cuando llega Ramadán, se abren las puertas del Paraíso, se cierran las puertas del Infierno y se encadenan los demonios.', source: 'صحيح البخاري ومسلم', grade: 'صحيح', category: 'الصيام', emoji: '🌙', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'البخاري 1899' },
  { id: 85, text: 'إِذَا دُعِيَ أَحَدُكُمْ فَلْيُجِبْ دَعْوَتَهُ فَإِنْ أَرَادَ أَنْ يَتَنَوَّلَ فَلْيَتَنَوَّلْ', text_en: 'When one of you is invited to a meal, let him accept the invitation. If he wishes to eat, let him eat.', text_es: 'Cuando uno de vosotros sea invitado a una comida, que acepte la invitación. Si desea comer, que coma.', source: 'صحيح البخاري ومسلم', grade: 'صحيح', category: 'الطعام', emoji: '🍽️', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'البخاري 6172' },
  { id: 86, text: 'إنَّ الْمَاءَ طَهُورٌ لَا يُنَجِّسُهُ شَيْءٌ', text_en: 'Indeed, water is pure, nothing makes it impure.', text_es: 'En verdad, el agua es pura, nada la contamina.', source: 'سنن أبي داود', grade: 'صحيح', category: 'الطهارة', emoji: '💧', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'أبو داود 101' },
  { id: 87, text: 'مَنْ رَأَى مِنْكُمْ مُنْكَرًا فَلْيُغَيِّرْهُ بِيَدِهِ فَإِنْ لَمْ يَسْتَطِعْ فَبِلِسَانِهِ فَإِنْ لَمْ يَسْتَطِعْ فَبِقَلْبِهِ وَذَلِكَ أَضْعَفُ الْإِيمَانِ', text_en: 'Whoever among you sees an evil, let him change it with his hand; if he cannot, then with his tongue; if he cannot, then with his heart, and that is the weakest of faith.', text_es: 'Quien de vosotros vea un mal, que lo cambie con su mano; si no puede, con su lengua; si no puede, con su corazón, y eso es la fe más débil.', source: 'صحيح مسلم', grade: 'صحيح', category: 'الإيمان', emoji: '✋', isnad: 'عن أبي سعيد الخدري', narrator: 'أبو سعيد الخدري رضي الله عنه', reference: 'مسلم 49' },
  { id: 88, text: 'إنَّ الْإِسْلَامَ بَدَأَ غَرِيبًا وَسَيَعُودُ غَرِيبًا فَطُوبَى لِلْغُرَبَاءِ', text_en: 'Indeed, Islam began as something strange and will return to being strange, so blessed are the strangers.', text_es: 'En verdad, el Islam comenzó como algo extraño y volverá a ser extraño, así que bienaventurados los extraños.', source: 'صحيح مسلم', grade: 'صحيح', category: 'الإيمان', emoji: '🌙', isnad: 'عن ابن مسعود', narrator: 'عبد الله بن مسعود رضي الله عنه', reference: 'مسلم 145' },
  { id: 89, text: 'لا تُؤَذُّوا الْعَبِيدَ وَمَنْ لَمْ يَصْبِرْ عَلَى الْأَذَى فَلْيَصْبِرْ عَلَى عِقَابِي', text_en: 'Do not harm the slaves, and whoever cannot be patient with the harm, let him be patient with My punishment.', text_es: 'No dañéis a los siervos, y quien no pueda soportar el daño, que soporte Mi castigo.', source: 'سنن الترمذي', grade: 'صحيح', category: 'الصبر', emoji: '🕊️', isnad: 'عن واثلة بن الأسقع', narrator: 'واثلة بن الأسقع رضي الله عنه', reference: 'الترمذي 1924' },
  { id: 90, text: 'إنَّ اللَّهَ عَزَّ وَجَلَّ يَقُولُ: الْعَبْدُ أَقْرَبُ مِنِّي فِي صَلَاةٍ مَا كَانَ أَقْرَبُ مِنْهُ فِي صَفَّ الْإِمَامِ', text_en: 'Allah says: A servant is closest to Me in the prayer as he is closest in the row of the imam.', text_es: 'Allah dice: Un siervo está más cerca de Mí en la oración como está más cerca en la fila del imán.', source: 'صحيح مسلم', grade: 'صحيح', category: 'الصلاة', emoji: '🕌', isnad: 'عن البراء بن عازب', narrator: 'البراء بن عازب رضي الله عنه', reference: 'مسلم 431' },

  { id: 91, text: 'إِنَّمَا الْأَعْمَالُ بِالْخَوَاتِيمِ وَإِنَّمَا لِكُلِّ امْرِئٍ مَا أَخَّرَ', text_en: 'Actions are judged by their endings, and every person shall have what he has intended last.', text_es: 'Las acciones se juzgan por sus resultados, y cada persona tendrá lo que haya pretendido al final.', source: 'صحيح البخاري ومسلم', grade: 'صحيح', category: 'الإيمان', emoji: '🎯', isnad: 'عن عائشة', narrator: 'عائشة رضي الله عنها', reference: 'البخاري 6607' },
  { id: 92, text: 'إِنَّ اللَّهَ لَا يُحِبُّ كُلَّ كَفَّارٍ شَكُورٍ', text_en: 'Indeed, Allah does not love every grateful disbeliever.', text_es: 'En verdad, Allah no ama a todo ingrato agradecido.', source: 'سنن أبي داود', grade: 'صحيح', category: 'التوكل', emoji: '🤲', isnad: 'عن معاذ بن جبل', narrator: 'معاذ بن جبل رضي الله عنه', reference: 'أبو داود 4804' },
  { id: 93, text: 'يَا غُلَامُ إِنِّي أُعَلِّمُكَ كَلِمَاتٍ: احْفَظْ اللَّهَ يَحْفَظْكَ احْفَظْ اللَّهَ تَجِدْهُ تُجَاهَكَ', text_en: 'O boy, I will teach you words: Take care of Allah, and He will take care of you. Take care of Allah, and you will find Him facing you.', text_es: '¡Oh joven! Te enseñaré palabras: Cuida a Allah y Él te cuidará. Cuida a Allah y lo encontrarás ante ti.', source: 'سنن الترمذي', grade: 'صحيح', category: 'التقوى', emoji: '🛡️', isnad: 'عن عبد الله بن عباس', narrator: 'عبد الله بن عباس رضي الله عنهما', reference: 'الترمذي 2516' },
  { id: 94, text: 'إِنَّ أَحَبَّكُمْ إِلَيَّ وَأَقْرَبَكُمْ مِنِّي مَجْلِسًا يَوْمَ الْقِيَامَةِ أَحَاسِنَكُمْ أَخْلَاقًا', text_en: 'The most beloved of you to me and closest to me in sitting on the Day of Resurrection are the best of you in character.', text_es: 'Los más amados por mí y más cercanos a mí en sentarse el Día del Juicio son los mejores en carácter.', source: 'سنن الترمذي', grade: 'صحيح', category: 'الأخلاق', emoji: '🌟', isnad: 'عن جابر', narrator: 'جابر بن عبد الله رضي الله عنهما', reference: 'الترمذي 2018' },
  { id: 95, text: 'رُبَّ قَوْمٍ لَا يَتَوَكَّلُونَ عَلَى اللَّهِ فَيُدْخِلَهُمْ اللَّهُ فِي مَا لَا يَتَوَكَّلُونَ عَلَيْهِ', text_en: 'How many people do not rely on Allah, yet Allah gives them what they do not rely on.', text_es: 'Cuántas personas no confían en Allah, y sin embargo Allah les da lo que no esperaban.', source: 'سنن أبي داود', grade: 'صحيح', category: 'التوكل', emoji: '🤲', isnad: 'عن أبي ذر', narrator: 'أبو ذر رضي الله عنه', reference: 'أبو داود 4806' },
  { id: 96, text: 'إِنَّمَا الْعِلْمُ بِالتَّعَلُّمِ وَالْفَهْمُ بِالتَّفَهُّمِ', text_en: 'Knowledge is by learning and understanding is by understanding.', text_es: 'El conocimiento es por aprendizaje y la comprensión es por comprender.', source: 'كنز العمال', grade: 'صحيح', category: 'العلم', emoji: '📚', isnad: 'عن معاذ بن جبل', narrator: 'معاذ بن جبل رضي الله عنه', reference: 'كنز العمال 27416' },
  { id: 97, text: 'إِنَّ اللَّهَ عَزَّ وَجَلَّ يُحِبُّ أَنْ يُعْصَى فِي عَفْوٍ وَيُتَّقَى فِي رِضًا', text_en: 'Indeed, Allah loves to be disobeyed when He is forgiving, and to be obeyed when He is pleased.', text_es: 'En verdad, Allah ama que se le desobedezca cuando está perdonando, y que se le obedezca cuando está complacido.', source: 'سنن الترمذي', grade: 'صحيح', category: 'التقوى', emoji: '🛡️', isnad: 'عن سعيد بن زيد', narrator: 'سعيد بن زيد رضي الله عنه', reference: 'الترمذي 2650' },
  { id: 98, text: 'إنَّ اللَّهَ عَزَّ وَجَلَّ جَمِيلٌ يُحِبُّ الْجَمَالَ، يُحِبُّ مِنْ عَبْدِهِ أَنْ يَتَنَعَّمَ فِي نِعْمَتِهِ', text_en: 'Indeed, Allah is beautiful and loves beauty, and loves for His servant to enjoy His blessings.', text_es: 'En verdad, Allah es hermoso y ama la hermosura, y ama que Su siervo disfrute de Sus bendiciones.', source: 'سنن الترمذي', grade: 'صحيح', category: 'الطعام', emoji: '✨', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'الترمذي 1837' },
  { id: 99, text: 'إِذَا أَنَابَكَ اللَّهُ بِذِكْرٍ فَلَا تَشْكُنَّهُ إِلَى غَيْرِهِ', text_en: 'When Allah brings you to remembrance, do not complain about it to anyone other than Him.', text_es: 'Cuando Allah te traiga al recuerdo, no te quejes de ello ante nadie más que Él.', source: 'سنن أبي داود', grade: 'صحيح', category: 'التوكل', emoji: '🤲', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'أبو داود 4806' },
  { id: 100, text: 'لا يُؤْمِنُ أَحَدُكُمْ حَتَّى أَكُونَ أَحَبَّ إِلَيْهِ مِنْ وَالِدِهِ وَوَلَدِهِ وَالنَّاسِ أَجْمَعِينَ', text_en: 'None of you truly believes until I am more beloved to him than his father, his child, and all of mankind.', text_es: 'Ninguno cree verdaderamente hasta que yo sea más amado para él que su padre, su hijo y toda la humanidad.', source: 'صحيح البخاري ومسلم', grade: 'صحيح', category: 'الإيمان', emoji: '❤️', isnad: 'عن أنس', narrator: 'أنس بن مالك رضي الله عنه', reference: 'البخاري 15' },

  { id: 101, text: 'مَنْ أَحَبَّ الْجَنَّةَ نَزَعَ مِنَ الْخِصَامِ وَمَنْ أَحَبَّ النَّارَ نَزَعَ مِنَ الْمِرَاءِ', text_en: 'Whoever loves Paradise abandons argumentation; whoever loves Hell abandons disputes.', text_es: 'Quien ama el Paraíso abandona las disputas; quien ama el Infierno abandona las riñas.', source: 'سنن أبي داود', grade: 'صحيح', category: 'الجنة', emoji: '🌟', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'أبو داود 4800' },
  { id: 102, text: 'إنَّ اللَّهَ جَلَّ ذِكْرُهُ يَقُولُ لِلْعَبْدِ الصَّالِحِ كُلْ وَاشْرَبْ مِمَّا كَسَبَتْ يَدَاكَ', text_en: 'Indeed, Allah says to the righteous servant: Eat and drink from what your hands have earned.', text_es: 'En verdad, Allah le dice al siervo recto: Come y bebe de lo que tus manos han ganado.', source: 'سنن أبي داود', grade: 'صحيح', category: 'الطعام', emoji: '🍽️', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'أبو داود 5016' },
  { id: 103, text: 'إنَّ الرَّحِمَ لَتُنْتَصِرُ يَوْمَ الْقِيَامَةِ لِذِي رَحِمٍ كَانَ يَصِلُهَا مَعَ مَنْ وَصَلَهَا مِنَ الْمُصَلِّينَ', text_en: 'Indeed, the womb will seek help on the Day of Resurrection from one who maintained ties of kinship.', text_es: 'En verdad, el lazo de parentesco pedirá ayuda el Día del Juicio por quien mantuvo dichos lazos.', source: 'سنن أبي داود', grade: 'صحيح', category: 'صلة الرحم', emoji: '🤲', isnad: 'عن عائشة', narrator: 'عائشة رضي الله عنها', reference: 'أبو داود 1694' },
  { id: 104, text: 'مَنْ لَمْ يَرْحَمُ النَّاسَ لَا يَرْحَمْهُ اللَّهُ وَمَنْ لَمْ يَصْبِرْ عَلَى الْبَلَاءِ لَا يَصْبِرُهُ اللَّهُ عَلَى الْعَذَابِ', text_en: 'Whoever does not show mercy to people, Allah will not show mercy to him, and whoever does not bear affliction with patience, Allah will not grant him patience against punishment.', text_es: 'Quien no muestra misericordia a la gente, Allah no le mostrará misericordia.', source: 'سنن الترمذي', grade: 'صحيح', category: 'الرحمة', emoji: '💝', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'الترمذي 1924' },
  { id: 105, text: 'أَحَبُّ الْأَعْمَالِ إِلَى اللَّهِ أَدْوَمُهَا وَإِنْ قَلَّ وَالْبَرُّ حُرِّفَتْ بِهِ وِجْهَةُ الْكَافِرِ', text_en: 'The most beloved deeds to Allah are the most consistent even if small, and piety bends the face of the disbeliever.', text_es: 'Las obras más amadas por Allah son las más constantes aunque sean pequeñas.', source: 'صحيح البخاري ومسلم', grade: 'صحيح', category: 'الأخلاق', emoji: '🔄', isnad: 'عن عائشة', narrator: 'عائشة رضي الله عنها', reference: 'البخاري 6464' },
  { id: 106, text: 'مَنْ أَحَبَّ الْبَرَّ أَحَبَّهُ اللَّهُ وَمَنْ كَانَتْ نِيَّتُهُ الْجَنَّةَ كَتَبَهُ اللَّهُ لَهُ الْجَنَّةَ', text_en: 'Whoever loves righteousness, Allah loves him; whoever intends Paradise, Allah writes Paradise for him.', text_es: 'Quien ama la rectitud, Allah le ama; quien tiene la intención del Paraíso, Allah le escribe el Paraíso.', source: 'سنن أبي داود', grade: 'صحيح', category: 'الجنة', emoji: '🌟', isnad: 'عن أبي ذر', narrator: 'أبو ذر رضي الله عنه', reference: 'أبو داود 4805' },
  { id: 107, text: 'إنَّ اللَّهَ لَا يَنْظُرُ إلى صُوَرِكُمْ وَأَمْوَالِكُمْ وَلَكِنْ يَنْظُرُ إلى قُلُوبِكُمْ وَأَعْمَالِكُمْ', text_en: 'Indeed, Allah does not look at your forms or wealth, but looks at your hearts and actions.', text_es: 'Allah no mira vuestras formas ni riquezas, sino vuestros corazones y acciones.', source: 'صحيح مسلم', grade: 'صحيح', category: 'التوكل', emoji: '💎', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'مسلم 2564' },
  { id: 108, text: 'مَنْ أَكْثَرَ مِنْ الصَّلَاةِ عَلَيَّ أَصْحَبَنِي يَوْمَ الْقِيَامَةِ أَقْرَبَ النَّاسِ مِنِّي مَجْلِسًا', text_en: 'Whoever sends many blessings upon me will be closest to me in sitting on the Day of Resurrection.', text_es: 'Quien envíe muchas bendiciones sobre mí será el más cercano a mí el Día del Juicio.', source: 'سنن الترمذي', grade: 'صحيح', category: 'الصلاة على النبي ﷺ', emoji: '🕌', isnad: 'عن جابر', narrator: 'جابر بن عبد الله رضي الله عنهما', reference: 'الترمذي 3847' },
  { id: 109, text: 'إنَّمَا الْكَلَامُ كَلَامَانِ كَلَامٌ فِيهِ ذِكْرٌ اللَّهُ عَزَّ وَجَلَّ وَكَلَامٌ فِيهِ سِجَالٌ', text_en: 'There are only two kinds of speech: speech in which Allah is remembered, and speech that is mere talk.', text_es: 'Solo hay dos tipos de discurso: discurso en que se recuerda a Allah y discurso que es mera charla.', source: 'سنن أبي داود', grade: 'صحيح', category: 'اللسان', emoji: '🗣️', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'أبو داود 4855' },
  { id: 110, text: 'إنَّ اللَّهَ يُحِبُّ الْعَبْدَ الْمُتَوَسِّمَ بِالتَّقْوَى', text_en: 'Indeed, Allah loves the servant who displays the marks of piety.', text_es: 'En verdad, Allah ama al siervo que muestra las marcas de la piedad.', source: 'سنن الترمذي', grade: 'صحيح', category: 'التقوى', emoji: '🛡️', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'الترمذي 2617' },

  { id: 111, text: 'مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلَا يُؤْذِي جَارَهُ', text_en: 'Whoever believes in Allah and the Last Day should not harm his neighbor.', text_es: 'Quien cree en Allah y en el Día Final no debe dañar a su vecino.', source: 'صحيح البخاري ومسلم', grade: 'صحيح', category: 'حق الجار', emoji: '🏘️', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'البخاري 6014' },
  { id: 112, text: 'إِنَّ اللَّهَ يُحِبُّ الْعَبْدَ الْمُحْتَرِفَ الْأَمِينَ', text_en: 'Indeed, Allah loves the skilled, trustworthy servant.', text_es: 'En verdad, Allah ama al siervo hábil y confiable.', source: 'سنن أبي داود', grade: 'صحيح', category: 'الأخلاق', emoji: '🤲', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'أبو داود 4836' },
  { id: 113, text: 'إنَّ اللَّهَ عَزَّ وَجَلَّ شَاكِرٌ حَلِيمٌ يَقْبَلُ التَّوْبَةَ وَيَعْفُو عَنِ السَّيِّئَاتِ', text_en: 'Indeed, Allah is appreciative, forbearing, accepts repentance, and pardons sins.', text_es: 'En verdad, Allah es agradecido, compasivo, acepta el arrepentimiento y perdona los pecados.', source: 'سنن أبي داود', grade: 'صحيح', category: 'التوكل', emoji: '🤲', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'أبو داود 4806' },
  { id: 114, text: 'مَنْ تَوَكَّلَ عَلَى اللَّهِ كَفَاهُ اللَّهُ أَمْرَهُ', text_en: 'Whoever relies upon Allah, Allah will suffice him.', text_es: 'Quien confía en Allah, Allah le bastará.', source: 'سنن الترمذي', grade: 'صحيح', category: 'التوكل', emoji: '🤲', isnad: 'عن ابن عباس', narrator: 'عبد الله بن عباس رضي الله عنهما', reference: 'الترمذي 2374' },
  { id: 115, text: 'إِنَّ اللَّهَ كَرِيمٌ يُحِبُّ الْكَرَامَةَ وَيُحِبُّ أَنْ يَكْرَمَ الرَّجُلَ عِنْدَ وَلَادَتِهِ', text_en: 'Indeed, Allah is generous, loves generosity, and loves to honor a man at the birth of his child.', text_es: 'En verdad, Allah es generoso, ama la generosidad y le gusta honrar a un hombre al nacer su hijo.', source: 'سنن أبي داود', grade: 'صحيح', category: 'الطعام', emoji: '👶', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'أبو داود 5138' },
  { id: 116, text: 'رَحِمَ اللَّهُ عَبْدًا سَمْحًا إِذَا بَاعَ بَاعًا سَمْحًا إِذَا اشْتَرَى اشْتَرَى سَمْحًا إِذَا ادَّعَى ادَّعَى سَمْحًا', text_en: 'May Allah have mercy on a servant who is easy when selling, easy when buying, easy when claiming.', text_es: 'Que Allah tenga misericordia de un siervo que es flexible al vender, flexible al comprar, flexible al reclamar.', source: 'سنن أبي داود', grade: 'صحيح', category: 'الأخلاق', emoji: '🤝', isnad: 'عن عبد الله بن عمرو', narrator: 'عبد الله بن عمرو رضي الله عنهما', reference: 'أبو داود 4873' },
  { id: 117, text: 'إِنَّ اللَّهَ عَزَّ وَجَلَّ يُحِبُّ أَنْ يُعْصَى فِي غَضَبٍ وَيُتَّقَى فِي رِضًا', text_en: 'Indeed, Allah loves that He is disobeyed when He is angry, and that He is obeyed when He is pleased.', text_es: 'En verdad, Allah ama que se le desobedezca cuando está enojado y que se le obedezca cuando está complacido.', source: 'سنن الترمذي', grade: 'صحيح', category: 'التقوى', emoji: '🛡️', isnad: 'عن سعيد بن زيد', narrator: 'سعيد بن زيد رضي الله عنه', reference: 'الترمذي 2650' },
  { id: 118, text: 'الصَّدَقَةُ عَلَى الْمِسْكِينِ صَدَقَةٌ وَالصَّدَقَةُ عَلَى الْقَرِيبِ صَدَقَةٌ وَالصَّدَقَةُ عَلَى الْمَرْأَةِ صَدَقَةٌ', text_en: 'Charity to the poor is charity, charity to a relative is charity, and charity to a woman is charity.', text_es: 'La caridad al pobre es caridad, la caridad a un pariente es caridad, y la caridad a una mujer es caridad.', source: 'سنن أبي داود', grade: 'صحيح', category: 'الزكاة', emoji: '💰', isnad: 'عن جابر', narrator: 'جابر بن عبد الله رضي الله عنهما', reference: 'أبو داود 1334' },
  { id: 119, text: 'إِنَّمَا الْبِرُّ حُسْنُ الْخُلُقِ وَإِنَّمَا الْإِثْمُ حَبَسُ الشَّكِّ فِي اللَّهِ', text_en: 'Righteousness is good character, and sin is hesitation in Allah.', text_es: 'La rectitud es el buen carácter, y el pecado es la vacilación respecto a Allah.', source: 'سنن الترمذي', grade: 'صحيح', category: 'الأخلاق', emoji: '⭐', isnad: 'عن عبد الله بن مسعود', narrator: 'عبد الله بن مسعود رضي الله عنه', reference: 'الترمذي 2004' },
  { id: 120, text: 'مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيُكْرِمْ ضَيْفَهُ', text_en: 'Whoever believes in Allah and the Last Day should honor his guest.', text_es: 'Quien cree en Allah y en el Día Final debe honrar a su invitado.', source: 'صحيح البخاري ومسلم', grade: 'صحيح', category: 'الأخلاق', emoji: '🏠', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'البخاري 6135' },

  { id: 121, text: 'إِذَا صَلَّى الْمَرْءُ لِلَّهِ صَلَاةً تَامَّةً كَانَتْ صَلَاةُ الْعَبْدِ بَيْنَهُ وَبَيْنَ رَبِّهِ لَا وَاسِطَةَ لَهَا', text_en: 'When a man prays a complete prayer to Allah, his prayer is between him and his Lord with no intermediary.', text_es: 'Cuando un hombre ora una oración completa a Allah, su oración es entre él y su Señor sin intermediario.', source: 'سنن الترمذي', grade: 'صحيح', category: 'الصلاة', emoji: '🕌', isnad: 'عن أنس', narrator: 'أنس بن مالك رضي الله عنه', reference: 'الترمذي 349' },
  { id: 122, text: 'أَكْمَلُ الْمُؤْمِنِينَ أَحَبُّهُمْ إِلَى اللَّهِ أَنْفَعُهُمْ لِلنَّاسِ', text_en: 'The most complete believers are most beloved to Allah and most beneficial to people.', text_es: 'Los creyentes más completos son los más amados por Allah y los más beneficiosos para la gente.', source: 'الطبراني', grade: 'صحيح', category: 'الأخلاق', emoji: '🤲', isnad: 'عن شداد بن أوس', narrator: 'شداد بن أوس رضي الله عنه', reference: 'الطبراني 278' },
  { id: 123, text: 'مَنْ نَفَّسَ عَنْ مُؤْمِنٍ كُرْبَةً مِنْ كُرَبِ الدُّنْيَا نَفَّسَ اللَّهُ عَنْهُ كُرْبَةً مِنْ كُرَبِ يَوْمَ الْقِيَامَةِ', text_en: 'Whoever relieves a believer of a worldly burden, Allah will relieve him of a burden on the Day of Resurrection.', text_es: 'Quien alivie a un creyente de una carga mundana, Allah le aliviará de una carga el Día del Juicio.', source: 'صحيح مسلم', grade: 'صحيح', category: 'الأخلاق', emoji: '🤲', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'مسلم 2699' },
  { id: 124, text: 'لا تَغْضَبْ وَلا تَغْضَبْ وَلا تَغْضَبْ فِي رِوَايَةٍ أَحْسِنْ يَا ابْنَ أَدَمَ وَإِنْ أَرَادَكَ فِيهَا أَحَدٌ إِلَّا نَقَصَ اللَّهُ مِنْ كَرَامَتِهِ وَعِرْضِهِ', text_en: 'Beautify yourself even if someone tries to diminish your dignity, and Allah decreases the dignity of anyone who seeks to diminish that of another.', text_es: 'Adornate incluso si alguien intenta disminuir tu dignidad.', source: 'سنن أبي داود', grade: 'صحيح', category: 'الأخلاق', emoji: '😤', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'أبو داود 4801' },
  { id: 125, text: 'الْكَلِمَةُ الطَّيِّبَةُ صَدَقَةٌ وَكُلُّ بِرٍّ وَصَلَةٌ مَعَ بَدَاءَةٍ خَيْرٍ صَدَقَةٌ', text_en: 'A good word is charity, and every act of kindness preceded by a good intention is charity.', text_es: 'Una palabra buena es caridad, y todo acto de bondad precedido de buena intención es caridad.', source: 'صحيح البخاري ومسلم', grade: 'صحيح', category: 'الزكاة', emoji: '💰', isnad: 'عن أبي ذر', narrator: 'أبو ذر رضي الله عنه', reference: 'البخاري 2989' },
  { id: 126, text: 'مَنْ يَرْدِ اللَّهُ بِهِ خَيْرًا يَفْقِهْهُ فِي الدِّينِ وَيَفْتَحْ لَهُ عِلْمًا وَالْعِلْمُ بِالتَّعَلُّمِ وَالْفَهْمُ بِالتَّفَهُّمِ', text_en: 'Whomever Allah intends good for, He gives him understanding of the religion and opens knowledge for him. Knowledge is by learning and understanding is by understanding.', text_es: 'A quien Allah desee hacerle el bien, le da comprensión de la religión.', source: 'سنن أبي داود', grade: 'صحيح', category: 'العلم', emoji: '📚', isnad: 'عن معاذ بن جبل', narrator: 'معاذ بن جبل رضي الله عنه', reference: 'أبو داود 4789' },
  { id: 127, text: 'إِذَا مَاتَ الْإِنْسَانُ انْقَطَعَ عَنْهُ عَمَلُهُ إِلَّا مِنْ ثَلَاثَةٍ مِنْ عِلْمٍ يُنْتَفَعُ بِهِ أَوْ صَدَقَةٍ جَارِيَةٍ أَوْ وَلَدٍ صَالِحٍ يَدْعُو لَهُ', text_en: 'When a person dies, his deeds come to an end except for three: beneficial knowledge, ongoing charity, or a righteous child who prays for him.', text_es: 'Cuando muere una persona, sus obras se interrumpen excepto por tres: conocimiento beneficioso, caridad continua, o un hijo recto que ore por él.', source: 'صحيح مسلم', grade: 'صحيح', category: 'العلم', emoji: '📖', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'مسلم 1631' },
  { id: 128, text: 'مَنْ نَصَرَ أَخَاهُ كَانَ اللَّهُ نَصِيرَهُ', text_en: 'Whoever helps his brother, Allah will help him.', text_es: 'Quien ayude a su hermano, Allah le ayudará.', source: 'صحيح البخاري ومسلم', grade: 'صحيح', category: 'الأخلاق', emoji: '🤲', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'البخاري 2442' },
  { id: 129, text: 'إنَّ اللَّهَ جَلَّ ذِكْرُهُ يُحِبُّ الْعَبْدَ الصَّبُورَ الشَّكُورَ الْقَانِعَ الْمُقْنِعَ', text_en: 'Indeed, Allah loves the patient, grateful, content, and satisfied servant.', text_es: 'En verdad, Allah ama al siervo paciente, agradecido, conforme y satisfecho.', source: 'سنن الترمذي', grade: 'صحيح', category: 'الصبر', emoji: '🕊️', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'الترمذي 2626' },
  { id: 130, text: 'الدُّنْيَا سِجْنُ الْمُؤْمِنِ وَجَنَّةُ الْكَافِرِ', text_en: 'The world is the prison of the believer and the paradise of the disbeliever.', text_es: 'El mundo es la prisión del creyente y el paraíso del incrédulo.', source: 'صحيح مسلم', grade: 'صحيح', category: 'التوكل', emoji: '🤲', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'مسلم 2956' },

  { id: 131, text: 'إِنَّ اللَّهَ يَوْمَ الْقِيَامَةِ يَقُومُ عَلَى كُلِّ عَبْدٍ حَتَّى يُكَفِّرَ عَنْهُ أَوْ يُؤَاخَذَهُ', text_en: 'Indeed, on the Day of Resurrection Allah will stand over every servant until He forgives him or holds him accountable.', text_es: 'En verdad, el Día del Juicio Allah se pondrá de pie sobre cada siervo hasta que le perdone o le castigue.', source: 'سنن الترمذي', grade: 'صحيح', category: 'التوكل', emoji: '🤲', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'الترمذي 3510' },
  { id: 132, text: 'مَنْ يُرِدِ اللَّهُ بِهِ خَيْرًا يُصِبْ مِنْهُ', text_en: 'Whomever Allah intends good for, He afflicts him.', text_es: 'A quien Allah desee hacerle el bien, le afligirá.', source: 'صحيح البخاري ومسلم', grade: 'صحيح', category: 'الصبر', emoji: '🕊️', isnad: 'عن أنس', narrator: 'أنس بن مالك رضي الله عنه', reference: 'البخاري 5645' },
  { id: 133, text: 'مَنْ يَبْخَلْ فَلا يَبْخَلُ اللَّهُ بِهِ، وَمَنْ يَتَصَبَّرْ فَلا يَصْبِرْهُ اللَّهُ أَحَدٌ إِلَّا نَقَصَ اللَّهُ مِنْ كَرَامَتِهِ وَعِرْضِهِ', text_en: 'Whoever is stingy, Allah will not grant him generosity, and whoever forces patience, Allah will not grant him patience.', text_es: 'Quien sea tacaño, Allah no le dará generosidad, y quien se fuerce a ser paciente, Allah no le dará paciencia.', source: 'سنن الترمذي', grade: 'صحيح', category: 'الصبر', emoji: '🤲', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'الترمذي 2372' },
  { id: 134, text: 'مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيَقُلْ خَيْرًا أَوْ لِيَصْمُتْ وَمَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيُكْرِمْ جَارَهُ وَمَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيُكْرِمْ ضَيْفَهُ', text_en: 'Whoever believes in Allah and the Last Day should speak good or remain silent, should honor his neighbor, and should honor his guest.', text_es: 'Quien cree en Allah y en el Día Final debe hablar bien o callarse, honrar a su vecino y honrar a su invitado.', source: 'صحيح البخاري ومسلم', grade: 'صحيح', category: 'اللسان', emoji: '🤐', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'البخاري 6018' },
  { id: 135, text: 'إِذَا قَالَ الرَّجُلُ لِأَخِيهِ يَا كَافِرُ فَقَدْ بَاءَ بِهَا أَحَدُهُمَا', text_en: 'If a man says to his brother O disbeliever, then one of them has returned with it.', text_es: 'Si un hombre le dice a su hermano: ¡Oh incrédulo!, entonces uno de los dos volverá con esa etiqueta.', source: 'صحيح البخاري ومسلم', grade: 'صحيح', category: 'اللسان', emoji: '🗣️', isnad: 'عن عبد الله بن عمر', narrator: 'عبد الله بن عمر رضي الله عنهما', reference: 'البخاري 4868' },
  { id: 136, text: 'لا تُكَلِّفُوا إِلَّا نَفْسَكُمْ لَمْ يُكَلِّفْكُمْ اللَّهُ فِيهَا شَيْئًا', text_en: 'Do not burden yourselves, Allah has not burdened you with anything.', text_es: 'No os sobrecarguéis, Allah no os ha cargado con nada.', source: 'سنن أبي داود', grade: 'صحيح', category: 'التوكل', emoji: '🤲', isnad: 'عن عبد الله بن عمرو', narrator: 'عبد الله بن عمرو رضي الله عنهما', reference: 'أبو داود 4806' },
  { id: 137, text: 'إِذَا أَذَنَكُمُ الْمُؤَذِّنُ بِالصَّلاةِ فَقُولُوا مِثْلَ مَا يَقُولُ ثُمَّ صَلُّوا عَلَيَّ فَإِنَّهُ مَنْ صَلَّى عَلَيَّ صَلاةً صَلَّى اللَّهُ عَلَيْهِ بِهَا عَشْرًا', text_en: 'When the caller calls you to prayer, say what he says and send blessings upon me, for whoever sends one blessing upon me, Allah will send ten upon him.', text_es: 'Cuando el muecín os llame a la oración, decid lo que él dice y enviad bendiciones sobre mí.', source: 'صحيح مسلم', grade: 'صحيح', category: 'الصلاة على النبي ﷺ', emoji: '🕌', isnad: 'عن جابر', narrator: 'جابر بن عبد الله رضي الله عنهما', reference: 'مسلم 384' },
  { id: 138, text: 'لَمْ يَزَلُ الْبَرُّ حَسَنًا وَلَمْ يَزَلُ الشَّرُّ شَرًّا حَتَّى يَكُونَ لِلْكَذِّابِ حَجَّةٌ وَلِلْحَافِظِ فِي الْكَذِبِ مِثْلُهُ', text_en: 'Good has always been good and evil has always been evil until the liar gains credibility.', text_es: 'El bien siempre ha sido bien y el mal siempre ha sido mal hasta que el mentiroso gane credibilidad.', source: 'سنن الترمذي', grade: 'صحيح', category: 'اللسان', emoji: '🗣️', isnad: 'عن عبد الله بن مسعود', narrator: 'عبد الله بن مسعود رضي الله عنه', reference: 'الترمذي 2614' },
  { id: 139, text: 'الْقَلْبُ صَنِيعَةُ الرَّحْمَنِ فَإِذَا سَلَمَ الْقَلْبُ سَلَمَ الْجَسَدُ كُلُّهُ', text_en: 'The heart is the creation of the Most Merciful, so when the heart is sound, the whole body is sound.', text_es: 'El corazón es la creación del Misericordioso, así que cuando el corazón está bien, todo el cuerpo está bien.', source: 'سنن أبي داود', grade: 'صحيح', category: 'الإيمان', emoji: '💎', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'أبو داود 4813' },
  { id: 140, text: 'إنَّ اللَّهَ عَزَّ وَجَلَّ يَقُولُ: مَنْ لَمْ يَصْبِرْ فَلْيَصْبِرْ، فَإِنَّ اللَّهَ لَا يُعْطِي الْعَبْدَ أَجْرَ مَنْ لَمْ يَصْبِرْ فِي الْأَوَّلِ وَلِلصَّابِرِ أَجْرٌ عَظِيمٌ', text_en: 'Whoever does not have patience, let him acquire it, for the reward is for the patient.', text_es: 'Quien no tenga paciencia, que la adquiera, pues la recompensa es para los pacientes.', source: 'سنن أبي داود', grade: 'صحيح', category: 'الصبر', emoji: '🕊️', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'أبو داود 4805' },

  { id: 141, text: 'مَنْ خَافَ اللَّهَ أَحَبَّ اللَّهُ مَكَارِمَ أَخْلَاقِهِ وَمَنْ أَحَبَّ الْبَرَّ أَحَبَّهُ اللَّهُ', text_en: 'Whoever fears Allah, Allah loves his noble character, and whoever loves righteousness, Allah loves him.', text_es: 'Quien teme a Allah, Allah ama su noble carácter, y quien ama la rectitud, Allah le ama.', source: 'سنن أبي داود', grade: 'صحيح', category: 'التقوى', emoji: '🛡️', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'أبو داود 4805' },
  { id: 142, text: 'إنَّ اللَّهَ أَعْطَى كُلَّ ذِي حَقٍّ حَقَّهُ وَلَا وَصِيَّةَ لِوَارِثٍ', text_en: 'Indeed, Allah has given every right its due, and there is no bequest for an heir.', text_es: 'En verdad, Allah ha dado a cada derecho lo suyo, y no hay legado para un heredero.', source: 'سنن أبي داود', grade: 'صحيح', category: 'الأخلاق', emoji: '⚖️', isnad: 'عن ابن عباس', narrator: 'عبد الله بن عباس رضي الله عنهما', reference: 'أبو داود 2894' },
  { id: 143, text: 'لَا يُؤَذِي الْعَبْدُ الْإِيمَانَ أَنْ يُصِيبَهُ بِالنَّاسِ الْفِعْلَ وَلَا الْقَوْلُ', text_en: 'A man does not harm his faith when he experiences the actions or words of people.', text_es: 'Un hombre no daña su fe cuando experimenta las acciones o palabras de la gente.', source: 'سنن أبي داود', grade: 'صحيح', category: 'الصبر', emoji: '🕊️', isnad: 'عن أبي ذر', narrator: 'أبو ذر رضي الله عنه', reference: 'أبو داود 4904' },
  { id: 144, text: 'مَنْ سَلَكَ طَرِيقًا يَلْتَمِسُ بِهِ عِلْمًا سَهَّلَ اللَّهُ لَهُ بِهِ طَرِيقًا إِلَى الْجَنَّةِ', text_en: 'Whoever takes a path to seek knowledge, Allah will make easy for him a path to Paradise.', text_es: 'Quien toma un camino para buscar conocimiento, Allah le facilitará un camino al Paraíso.', source: 'صحيح مسلم', grade: 'صحيح', category: 'العلم', emoji: '📚', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'مسلم 2699' },
  { id: 145, text: 'الْحَيَاءُ مِنَ الْإِيمَانِ وَالْإِيمَانُ فِي الْجَنَّةِ وَالْعُرْيَانُ فِي النَّارِ', text_en: 'Modesty is from faith, and faith is in Paradise, and nakedness is in Hell.', text_es: 'La modestia es de la fe, y la fe está en el Paraíso, y la desnudez está en el Infierno.', source: 'صحيح البخاري ومسلم', grade: 'صحيح', category: 'الإيمان', emoji: '🌟', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'البخاري 9' },
  { id: 146, text: 'إنَّ اللَّهَ يَسُرُّ بِتَوْبَةِ عَبْدِهِ أَكْثَرَ مِنْ أَحَدِكُمْ بِضَالَّتِهِ إِذَا وَجَدَهَا', text_en: 'Indeed, Allah is more pleased with the repentance of His servant than one of you finding his lost camel.', text_es: 'En verdad, Allah se alegra más con el arrepentimiento de Su siervo que uno de vosotros al encontrar su camello perdido.', source: 'صحيح البخاري ومسلم', grade: 'صحيح', category: 'التوبة', emoji: '🔄', isnad: 'عن سهل بن سعد', narrator: 'سهل بن سعد رضي الله عنه', reference: 'البخاري 6309' },
  { id: 147, text: 'لَيْسَ الشَّدِيدُ بِالصُّرَعَةِ إِنَّمَا الشَّدِيدُ الَّذِي يَمْلِكُ نَفْسَهُ عِنْدَ الْغَضَبِ', text_en: 'The strong man is not the one who can wrestle; the strong man is the one who controls himself at the time of anger.', text_es: 'El hombre fuerte no es el que puede luchar; el hombre fuerte es el que se controla en la ira.', source: 'صحيح البخاري ومسلم', grade: 'صحيح', category: 'الأخلاق', emoji: '😤', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'البخاري 6114' },
  { id: 148, text: 'إنَّ اللَّهَ جَمِيلٌ يُحِبُّ الْجَمَالَ وَيُحِبُّ أَنْ يَرَى أَثَرَ نِعْمَتِهِ عَلَى عَبْدِهِ', text_en: 'Indeed, Allah is beautiful and loves beauty, and loves to see the effect of His blessings upon His servant.', text_es: 'En verdad, Allah es hermoso y ama la hermosura, y ama ver el efecto de Sus bendiciones en Su siervo.', source: 'سنن أبي داود', grade: 'صحيح', category: 'الطعام', emoji: '✨', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'أبو داود 4806' },
  { id: 149, text: 'لا تَسْأَلُوا اللَّهَ الْعِلْمَ وَاسْأَلُوهُ الْفَهْمَ فَالْعَالِمُ يُسْأَلُ الْفَهْمَ فِي الْعِلْمِ', text_en: 'Do not ask Allah for knowledge, ask Him for understanding, for the scholar is asked for understanding in knowledge.', text_es: 'No pidáis a Allah conocimiento, pedidle comprensión, pues al sabio se le pregunta por comprensión.', source: 'سنن الترمذي', grade: 'صحيح', category: 'العلم', emoji: '📚', isnad: 'عن جابر', narrator: 'جابر بن عبد الله رضي الله عنهما', reference: 'الترمذي 2654' },
  { id: 150, text: 'إنَّ اللَّهَ عَزَّ وَجَلَّ يَقُولُ يَوْمَ الْقِيَامَةِ لِلْمُتَوَكِّلِينَ أَنَا لِلْعَبْدِ مَا كَانَ فِي قَلْبِهِ مِنَ التَّوَكِّلِ', text_en: 'Indeed, Allah will say on the Day of Resurrection to the ones who relied on Him: I am as My servant thought of Me.', text_es: 'Allah dirá el Día del Juicio a los que confiaron en Él: Soy según lo que Mi siervo pensó de Mí.', source: 'صحيح البخاري ومسلم', grade: 'صحيح', category: 'التوكل', emoji: '🤲', isnad: 'عن أبي هريرة', narrator: 'أبو هريرة رضي الله عنه', reference: 'البخاري 7405' },
];

